    private static func runNotationLegendTest(_ referenceFileName: String, _ startBar: Double, _ barCount: Double, _ songBook: Bool, _ fileName: String = "notation-legend.gp") async throws {
        let settings: Settings = Settings()
        settings.display.layoutMode = LayoutMode.Horizontal
        settings.display.startBar = startBar
        settings.display.barCount = barCount
        if songBook {
            settings.setSongBookModeSettings()
        }
        let inputFileData: Uint8Array = await TestPlatformPartials.loadFile("test-data/visual-tests/notation-legend/\((fileName).toTemplate())")
        let score: Score = try ScoreLoader.loadScoreFromBytes(inputFileData, settings)
        let o: VisualTestOptions = VisualTestOptions(score, List<VisualTestRun>(VisualTestRun(-1.0, "test-data/visual-tests/notation-legend/\((referenceFileName).toTemplate())")), settings)
        try await VisualTestHelper.runVisualTestFull(o)
    }

